package realestate;
import realestate.dao.*;import realestate.model.*;import realestate.service.*;import java.util.*;import java.math.*;import java.sql.*;
public class Main {
 private static final Scanner in=new Scanner(System.in);private static final UserDAO users=new UserDAO();private static final PropertyDAO props=new PropertyDAO();private static final InterestDAO interests=new InterestDAO();private static final AuthenticationService auth=new AuthenticationService(users);private static final PropertyService propertyService=new PropertyService(props);
 public static void main(String[]args){System.out.println("=== Real Estate Property Listing System ===");while(true){try{System.out.println("\n1 Register  2 Login  0 Exit");switch(readInt("Choice: ")){case 1->register();case 2->session();case 0->{System.out.println("Goodbye.");return;}default->System.out.println("Choose 0, 1, or 2.");}}catch(Exception e){showError(e);}}}
 private static void register()throws SQLException{String n=read("Name: "),e=read("Email: "),p=read("Phone: "),r=read("Role (BUYER/SELLER): ").toUpperCase(Locale.ROOT);char[]pw=read("Password (8+ chars): ").toCharArray();System.out.println("Registered user #"+auth.register(n,e,p,r,pw));Arrays.fill(pw,'\0');}
 private static void session()throws SQLException{String email=read("Email: ");char[]pw=read("Password: ").toCharArray();User u=auth.login(email,pw);Arrays.fill(pw,'\0');if(u==null){System.out.println("Invalid email or password.");return;}System.out.println("Welcome, "+u.getName()+" ["+u.getRole()+"]");boolean done=false;while(!done){try{if(u instanceof Buyer)done=buyer((Buyer)u);else if(u instanceof Seller)done=seller((Seller)u);else done=admin((Admin)u);}catch(Exception e){showError(e);}}}
 private static boolean buyer(Buyer u)throws SQLException{System.out.println("\nBUYER: 1 Browse 2 Search 3 Express interest 4 Logout");switch(readInt("Choice: ")){case 1->show(props.browse());case 2->search();case 3->{long id=readLong("Property ID: ");if(!props.existsAvailable(id))System.out.println("Available property not found.");else if(interests.express(u.getId(),id))System.out.println("Interest recorded.");else System.out.println("You already expressed interest.");}case 4->{return true;}default->System.out.println("Invalid option.");}return false;}
 private static boolean seller(Seller u)throws SQLException{System.out.println("\nSELLER: 1 Add 2 My listings 3 Update 4 Deactivate 5 View interest 6 Logout");switch(readInt("Choice: ")){case 1->add(u);case 2->show(props.mine(u.getId()));case 3->update(u);case 4->{long id=readLong("Property ID: ");System.out.println(propertyService.deactivate(id,u.getId(),false)?"Listing deactivated.":"Not found or not yours.");}case 5->interests.listForSeller(u.getId());case 6->{return true;}default->System.out.println("Invalid option.");}return false;}
 private static boolean admin(Admin u)throws SQLException{System.out.println("\nADMIN: 1 All properties 2 Users 3 Deactivate listing 4 Interests 5 Logout");switch(readInt("Choice: ")){case 1->show(props.all());case 2->users.listUsers();case 3->{long id=readLong("Property ID: ");System.out.println(propertyService.deactivate(id,u.getId(),true)?"Listing deactivated.":"Not found.");}case 4->interests.listAll();case 5->{return true;}default->System.out.println("Invalid option.");}return false;}
 private static void add(Seller u)throws SQLException{String t=read("Title: "),type=read("Type HOUSE/APARTMENT/LAND/COMMERCIAL: ").toUpperCase(Locale.ROOT),loc=read("Location: ");BigDecimal price=money("Price: ");int beds=readInt("Bedrooms (0 for n/a): "),baths=readInt("Bathrooms (0 for n/a): ");double area=readDouble("Area sqft: ");String desc=read("Description: ");Property x=make(0,u.getId(),t,loc,price,beds,baths,area,desc,"AVAILABLE",type);System.out.println("Created listing #"+propertyService.add(x));}
 private static void update(Seller u)throws SQLException{long id=readLong("Property ID: ");Property old=props.mine(u.getId()).stream().filter(x->x.getId()==id).findFirst().orElse(null);if(old==null){System.out.println("Your listing not found.");return;}old.setTitle(read("New title: "));old.setLocation(read("New location: "));old.setPrice(money("New price: "));old.setBedrooms(readInt("Bedrooms: "));old.setBathrooms(readInt("Bathrooms: "));old.setArea(readDouble("Area sqft: "));old.setDescription(read("Description: "));System.out.println(propertyService.update(old,u.getId(),false)?"Updated.":"Update failed.");}
 private static void search()throws SQLException{String loc=read("Location contains (blank for any): "),type=read("Type HOUSE/APARTMENT/LAND/COMMERCIAL/ALL: ").toUpperCase(Locale.ROOT),m=read("Maximum price (blank for any): ");BigDecimal max=m.isBlank()?null:new BigDecimal(m);int beds=readInt("Minimum bedrooms (-1 for any): ");show(propertyService.search(loc,type,max,beds));}
 private static Property make(long id,long seller,String t,String loc,BigDecimal p,int b,int ba,double a,String d,String st,String type){return switch(type){case "HOUSE"->new House(id,seller,t,loc,p,b,ba,a,d,st);case "APARTMENT"->new Apartment(id,seller,t,loc,p,b,ba,a,d,st);case "LAND"->new Land(id,seller,t,loc,p,b,ba,a,d,st);case "COMMERCIAL"->new CommercialProperty(id,seller,t,loc,p,b,ba,a,d,st);default->throw new IllegalArgumentException("Unsupported property type.");};}
 private static void show(List<Property> ps){if(ps.isEmpty())System.out.println("No listings found.");else ps.forEach(p->System.out.println(p.displayDetails()+"\n  "+p.getDescription()));}
 private static String read(String prompt){System.out.print(prompt);return in.nextLine().trim();}private static int readInt(String p){return Integer.parseInt(read(p));}private static long readLong(String p){return Long.parseLong(read(p));}private static double readDouble(String p){return Double.parseDouble(read(p));}private static BigDecimal money(String p){return new BigDecimal(read(p));}private static void showError(Exception e){if(e instanceof SQLIntegrityConstraintViolationException)System.out.println("That email is already registered.");else if(e instanceof IllegalArgumentException)System.out.println("Input error: "+e.getMessage());else System.out.println("Operation failed: "+e.getMessage());}
}
